mapper.select:
SELECT task_id AS id, version_id AS versionId
FROM version_task
WHERE workspace_id = #{workspaceId}

mapper.delete:
DELETE vt FROM version_task vt
INNER JOIN project_version pv ON pv.id = vt.version_id AND pv.workspace_id = vt.workspace_id
WHERE vt.workspace_id = #{workspaceId} AND pv.req_id = #{reqId}
